function grade(score) {
  if (score >= 90) return 'A';
  else if (score >= 75) return 'B';
  else if (score >= 60) return 'C';
  return 'Needs work';
}

console.log(grade(91)); // 'A'
console.log(grade(75)); // 'B'
console.log(grade(12)); // 'Needs work'

function shippingDays(region) {
  switch (region) {
    case 'metro':
    case 'city':
      return 1;
    case 'rural':
      return 4;
    default:
      return 7;
  }
}

console.log(shippingDays('city'));  // 1
console.log(shippingDays('island')); // 7

