// Nested
function discountNested(user, cart) {
  if (user) {
    if (cart.items.length > 0) {
      if (user.isMember) return cart.total * 0.9;
      else return cart.total;
    } else return 0;
  } else return 0;
}

// Guarded
function discount(user, cart) {
  if (!user) return 0;
  if (cart.items.length === 0) return 0;
  return user.isMember ? cart.total * 0.9 : cart.total;
}

