function total(taxRate = 0.18, ...amounts) {
  const sum = amounts.reduce((acc, n) => acc + n, 0);
  return sum * (1 + taxRate);
}

console.log(total(undefined, 100, 50)); // 177
console.log(total(0, 100, 50));         // 150
console.log(total(null, 100));          // 100 * (1 + null) -> 100

