const counter = {
  count: 0,
  increment() {
    this.count += 1;
    return this.count;
  },
};

console.log(counter.increment()); // 1

const detached = counter.increment;
try {
  detached();
} catch (error) {
  console.log(error.name); // 'TypeError' (this is undefined)
}

const bound = counter.increment.bind(counter);
console.log(bound()); // 2

const cart = {
  items: [10, 20],
  taxRate: 0.1,
  totals() {
    return this.items.map((price) => price * (1 + this.taxRate));
  },
};

console.log(cart.totals()); // [11, 22]
